import{_ as s,o as n,c as e,a2 as t}from"./chunks/framework.BWixA7XM.js";const b=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"转储到模型","text":"3DMigoto 数据提取全流程教程","tagline":"从一个 FrameAnalysis 转储目录，走到一个能在 Blender 里编辑、能改回游戏里的模型","actions":[{"theme":"brand","text":"开始阅读","link":"/guide/"},{"theme":"alt","text":"直接看案例","link":"/case/7ad7e69e"}]},"features":[{"title":"讲清原理，不只给脚本","details":"为什么同一个模型有两份顶点？为什么 GPU 蒙皮要从 pointlist draw 取数据？每一个\\"为什么\\"都追到 dx11 调用和日志原话。"},{"title":"每一步都能验证","details":"顶点数对不对、布局猜得准不准、绕序朝向有没有反、UV 要不要翻转 —— 每个环节都给出可执行的校验手段，不靠\\"看起来差不多\\"。"},{"title":"最终能改回游戏","details":"不满足于\\"导进 Blender 看看\\"。顶点色按 uint8 逐字节保留、UV 存原始字节，保证改完能无损写回去。"}]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1795572648000}'),l={name:"index.md"};function p(r,a,i,d,o,c){return n(),e("div",null,[...a[0]||(a[0]=[t(`<h2 id="这套教程解决什么问题" tabindex="-1">这套教程解决什么问题 <a class="header-anchor" href="#这套教程解决什么问题" aria-label="Permalink to &quot;这套教程解决什么问题&quot;">​</a></h2><p>你想改一个游戏的模型。游戏用 <strong>3DMigoto</strong> 注入，能抓 <strong>FrameAnalysis</strong> 转储。但转储目录里是一堆 <code>000081-ib=1a2b3c4d-vs=...-ps=....buf</code> 这样的文件，名字里只有哈希，没有任何说明告诉你：</p><ul><li>哪个 <code>.buf</code> 是这个模型的顶点？</li><li>数据是 12 字节一顶点还是 40 字节一顶点？前 12 字节是坐标，那后 28 字节是什么？</li><li>为什么顶点数和我数的差一点？</li><li>为什么导出来的人形是躺着的，或者摆着一个踢腿姿势？</li><li>为什么进 Blender 之后颜色是彩虹噪点？</li></ul><p>这套教程把这些逐个拆开。不假设你有 SSMT 这类工具，只用 Python + numpy + 一本 dx11 手册，从转储一路走到 Blender 里能编辑的网格。</p><h2 id="路线图" tabindex="-1">路线图 <a class="header-anchor" href="#路线图" aria-label="Permalink to &quot;路线图&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>FrameAnalysis 转储目录</span></span>
<span class="line"><span>       │</span></span>
<span class="line"><span>       ├─ log.txt ──────────────► 谁画了谁（draw → 资源哈希 → 真实文件）</span></span>
<span class="line"><span>       ├─ 000081-ib=….txt ──────► 索引缓冲区长什么样</span></span>
<span class="line"><span>       ├─ 000081-vb0.txt ───────► 输入布局：每顶点有哪些字段、各占几字节</span></span>
<span class="line"><span>       └─ deduped\\*.buf ────────► 真正的二进制数据</span></span>
<span class="line"><span>                │</span></span>
<span class="line"><span>                ▼</span></span>
<span class="line"><span>        ① 锁定目标 IB        找到 8 位 IB 哈希，认清它的 draw</span></span>
<span class="line"><span>                │</span></span>
<span class="line"><span>        ② 搞懂数据类型        每顶点 stride 怎么拆成字段（GameType）</span></span>
<span class="line"><span>                │</span></span>
<span class="line"><span>        ③ 切片提取            按 offset 切字节 → 顶点 / 索引 / 贴图</span></span>
<span class="line"><span>                │</span></span>
<span class="line"><span>        ④ 坐标与朝向          定 up 轴、定绕序、UV 是否翻转</span></span>
<span class="line"><span>                │</span></span>
<span class="line"><span>        ⑤ 导入 Blender        OBJ 或脚本，顶点组 / 顶点色 / 多套 UV</span></span>
<span class="line"><span>                │</span></span>
<span class="line"><span>        ⑥ 做回 Mod            反变换写回，坐标 / UV / 顶点色都要能还原</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br></div></div><h2 id="三条阅读路径" tabindex="-1">三条阅读路径 <a class="header-anchor" href="#三条阅读路径" aria-label="Permalink to &quot;三条阅读路径&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">只想赶紧把模型导出来</p><p>跳到<a href="/SSMT4-Tutorial/guide/dump/find-ib">锁定目标 IB</a> → <a href="/SSMT4-Tutorial/guide/extract/layout">读输入布局</a> → <a href="/SSMT4-Tutorial/guide/blender/obj">OBJ 路线</a>。半小时能出结果。</p></div><div class="tip custom-block"><p class="custom-block-title">想知道为什么会踩坑</p><p>从<a href="/SSMT4-Tutorial/guide/dump/anatomy">认识 FrameAnalysis 目录</a>读起。重点看<a href="/SSMT4-Tutorial/guide/gametype/preskinning">GPU 与 CPU 预蒙皮</a>那一节 —— 大部分&quot;模型姿势不对&quot;的问题都出在这里。</p></div><div class="tip custom-block"><p class="custom-block-title">想做 Mod，改完还要能写回去</p><p><a href="/SSMT4-Tutorial/guide/mod/writeback">第五步：做回 Mod</a> 是必读的。前面每一步都要按&quot;能还原&quot;的标准来做，事后补救来不及。</p></div><h2 id="关于术语" tabindex="-1">关于术语 <a class="header-anchor" href="#关于术语" aria-label="Permalink to &quot;关于术语&quot;">​</a></h2><p>教程里会出现几个高频词，先统一一下：</p><table tabindex="0"><thead><tr><th>词</th><th>意思</th></tr></thead><tbody><tr><td><strong>转储 / Dump</strong></td><td>3DMigoto 按 F8 生成的 FrameAnalysis 目录</td></tr><tr><td><strong>IB</strong></td><td>Index Buffer，索引缓冲区。一个&quot;模型&quot;通常由一个 IB 定义它的面</td></tr><tr><td><strong>VB</strong></td><td>Vertex Buffer，顶点缓冲区。位置、法线、UV 都在里面</td></tr><tr><td><strong>draw / drawcall</strong></td><td>一次绘制调用。同一个 IB 可能被多个 draw 用不同顶点范围画</td></tr><tr><td><strong>数据类型 / GameType</strong></td><td>一套&quot;每顶点字节怎么拆成字段&quot;的说明书</td></tr><tr><td><strong>预蒙皮 / PreSkinning</strong></td><td>骨骼绑定是在 GPU 还是 CPU 上算的，决定了数据藏在哪个缓冲里</td></tr></tbody></table><p>完整定义见<a href="/SSMT4-Tutorial/dev/glossary">术语表</a>。</p>`,14)])])}const m=s(l,[["render",p]]);export{b as __pageData,m as default};
